use crate::aap::caps::http_client;
use crate::wasi::clocks::wall_clock;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything except RFC 3986 unreserved characters.
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        let unreserved = b.is_ascii_alphanumeric() || matches!(b, b'-' | b'.' | b'_' | b'~');
        if unreserved {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0F) as usize] as char);
        }
    }
    out
}

/// Convert seconds since the Unix epoch to a `YYYY-MM-DD` string.
/// The result is always exactly 10 characters: years past 9999 are clamped.
fn date_from_unix_seconds(secs: u64) -> String {
    let days = secs / 86_400;

    // Howard Hinnant's civil_from_days, specialised to non-negative day counts.
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }

    if y > 9_999 {
        return String::from("9999-12-31");
    }

    let s = format!("{:04}-{:02}-{:02}", y, m, d);
    debug_assert_eq!(s.len(), 10);
    s
}

impl Guest for Node {
    fn run(tick: Tick) -> RunInfo {
        // Enrichment fetch, as approved. The result does not affect the output,
        // and a transport failure is returned as a value so it cannot fail the tick.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&tick.reason));
        let _enrichment = http_client::fetch(&url);

        let now = wall_clock::now();
        let started = now.seconds;
        let date = date_from_unix_seconds(started);

        RunInfo { date, started }
    }
}

export!(Node);
